const { createApp } = require("./app");
const { sequelize } = require("./models");
const { seed } = require("./seed");

const PORT = 3001;

async function start() {
  try {
    await sequelize.sync({ alter: true });
    await seed();

    const app = createApp();
    app.listen(PORT, () =>
      console.log(`Server running on http://localhost:${PORT}`),
    );
  } catch (error) {
    console.error("Unable to start:", error);
    process.exit(1);
  }
}

if (require.main === module) {
  start();
}

module.exports = { start };

import { useEffect, useState } from "react";
import { getComments } from "./api";

const initialCommentState = {
  comments: [],
  error: null,
};

function useComments(slug) {
  const [state, setState] = useState(initialCommentState);

  useEffect(() => {
    let isActive = true;

    setState(initialCommentState);

    getComments(slug)
      .then((comments) => {
        if (isActive) {
          setState({ comments, error: null });
        }
      })
      .catch((err) => {
        if (isActive) {
          setState({ comments: [], error: err.message });
        }
      });

    return () => {
      isActive = false;
    };
  }, [slug]);

  return state;
}

export default useComments;

"use strict";

const { Sequelize, DataTypes, Model } = require("sequelize");

const HIDDEN_ATTRIBUTES = {
  user: ["id", "updatedAt", "createdAt"],
  article: ["id", "userId"],
  comment: ["articleId", "userId"],
};

function serializeWithout(model, hiddenAttributes) {
  const data = { ...model.get() };

  hiddenAttributes.forEach((attribute) => {
    delete data[attribute];
  });

  return data;
}

const sequelize = new Sequelize({
  dialect: "sqlite",
  storage: ":memory:",
  logging: false,
});

class User extends Model {
  static associate() {
    this.hasMany(Article, { foreignKey: "userId", onDelete: "CASCADE" });
    this.hasMany(Comment, { foreignKey: "userId" });
  }

  toJSON() {
    return serializeWithout(this, HIDDEN_ATTRIBUTES.user);
  }
}

class Article extends Model {
  static associate() {
    this.belongsTo(User, { foreignKey: "userId", as: "author" });
    this.hasMany(Comment, { foreignKey: "articleId", onDelete: "CASCADE" });
  }

  toJSON() {
    return serializeWithout(this, HIDDEN_ATTRIBUTES.article);
  }
}

class Comment extends Model {
  static associate() {
    this.belongsTo(Article, { foreignKey: "articleId" });
    this.belongsTo(User, { as: "author", foreignKey: "userId" });
  }

  toJSON() {
    return serializeWithout(this, HIDDEN_ATTRIBUTES.comment);
  }
}

User.init(
  { username: DataTypes.STRING },
  { sequelize, modelName: "User" },
);

Article.init(
  { slug: DataTypes.STRING },
  { sequelize, modelName: "Article" },
);

Comment.init(
  {
    id: {
      allowNull: false,
      autoIncrement: true,
      primaryKey: true,
      type: DataTypes.INTEGER,
    },
    body: DataTypes.TEXT,
  },
  { sequelize, modelName: "Comment" },
);

User.associate();
Article.associate();
Comment.associate();

module.exports = { sequelize, User, Article, Comment };

